-- SwapLoop Module B — admin database seed
-- Target: MySQL 8.0+ or MariaDB 10.5+
-- Database: swaploop_admin
-- Plaintext password for all staff users: password123
-- password_hash uses bcrypt
-- Timezone: Asia/Shanghai (+08:00)
-- Billing volumes are individual usage_events; aggregate by calendar month in +08:00

SET NAMES utf8mb4;
SET time_zone = '+08:00';
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `swaploop_admin`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `swaploop_admin`;

DROP TABLE IF EXISTS `usage_events`;
DROP TABLE IF EXISTS `discount_tiers`;
DROP TABLE IF EXISTS `drivers`;
DROP TABLE IF EXISTS `staff_station_assignments`;
DROP TABLE IF EXISTS `units`;
DROP TABLE IF EXISTS `staff_users`;
DROP TABLE IF EXISTS `partners`;
DROP TABLE IF EXISTS `subscription_plans`;
DROP TABLE IF EXISTS `stations`;

CREATE TABLE `subscription_plans` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `code` VARCHAR(64) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `monthly_base_fee_yuan` INT NOT NULL,
  `included_quota` INT NOT NULL,
  `overage_rate_yuan` INT NOT NULL,
  UNIQUE KEY `uq_subscription_plans_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `discount_tiers` (
  `id` INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `plan_id` VARCHAR(64) NOT NULL,
  `min_completed_uses` INT NOT NULL,
  `max_completed_uses` INT NULL,
  `discount_percent` INT NOT NULL,
  CONSTRAINT `fk_discount_tiers_plan`
    FOREIGN KEY (`plan_id`) REFERENCES `subscription_plans` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `partners` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `name` VARCHAR(120) NOT NULL,
  `status` VARCHAR(32) NOT NULL,
  `contact_name` VARCHAR(80) NOT NULL,
  `fleet_size` INT NOT NULL,
  `plan_id` VARCHAR(64) NOT NULL,
  UNIQUE KEY `uq_partners_name` (`name`),
  CONSTRAINT `fk_partners_plan`
    FOREIGN KEY (`plan_id`) REFERENCES `subscription_plans` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stations` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `name` VARCHAR(120) NOT NULL,
  `type` VARCHAR(32) NOT NULL,
  `lifecycle_state` VARCHAR(32) NOT NULL,
  `address` VARCHAR(200) NOT NULL,
  `latitude` DECIMAL(9,6) NOT NULL,
  `longitude` DECIMAL(9,6) NOT NULL,
  `suspension_reason` VARCHAR(500) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `units` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `station_id` VARCHAR(64) NOT NULL,
  `unit_type` VARCHAR(32) NOT NULL,
  `label` VARCHAR(40) NOT NULL,
  `status` VARCHAR(32) NOT NULL,
  `battery_type` VARCHAR(32) NULL,
  `connector_type` VARCHAR(32) NULL,
  `blocked_reason` VARCHAR(500) NULL,
  UNIQUE KEY `uq_units_station_label` (`station_id`, `label`),
  CONSTRAINT `fk_units_station`
    FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_users` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `email` VARCHAR(255) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `display_name` VARCHAR(80) NOT NULL,
  `role` VARCHAR(32) NOT NULL,
  `status` VARCHAR(32) NOT NULL,
  `partner_id` VARCHAR(64) NULL,
  UNIQUE KEY `uq_staff_users_email` (`email`),
  CONSTRAINT `fk_staff_users_partner`
    FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `staff_station_assignments` (
  `staff_id` VARCHAR(64) NOT NULL,
  `station_id` VARCHAR(64) NOT NULL,
  PRIMARY KEY (`staff_id`, `station_id`),
  CONSTRAINT `fk_ssa_staff`
    FOREIGN KEY (`staff_id`) REFERENCES `staff_users` (`id`),
  CONSTRAINT `fk_ssa_station`
    FOREIGN KEY (`station_id`) REFERENCES `stations` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `drivers` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `partner_id` VARCHAR(64) NOT NULL,
  `employee_code` VARCHAR(32) NOT NULL,
  `display_name` VARCHAR(80) NOT NULL,
  `email` VARCHAR(255) NOT NULL,
  `status` VARCHAR(32) NOT NULL,
  UNIQUE KEY `uq_drivers_email` (`email`),
  UNIQUE KEY `uq_drivers_partner_code` (`partner_id`, `employee_code`),
  CONSTRAINT `fk_drivers_partner`
    FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `usage_events` (
  `id` VARCHAR(64) NOT NULL PRIMARY KEY,
  `partner_id` VARCHAR(64) NOT NULL,
  `driver_id` VARCHAR(64) NOT NULL,
  `service_type` VARCHAR(32) NOT NULL,
  `completed_at` DATETIME NOT NULL,
  KEY `idx_usage_partner_completed` (`partner_id`, `completed_at`),
  CONSTRAINT `fk_usage_partner`
    FOREIGN KEY (`partner_id`) REFERENCES `partners` (`id`),
  CONSTRAINT `fk_usage_driver`
    FOREIGN KEY (`driver_id`) REFERENCES `drivers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;

